function zhuyinCandidates(input){
  if(!input) return [];
  const hasTone=/[ˉˊˇˋ˙]$/.test(input);
  if(hasTone){
    // 按下聲調後只顯示教育部資料中完全相同讀音的候選。
    return (MOE_EXACT[input]||[]).slice(0,30);
  }
  // 尚未選聲調：先顯示完整基本音節的所有實際讀音候選。
  let result=[...(MOE_BASE[input]||[])];

  // 部分輸入（例如 ㄅ、ㄅㄤ）可預覽真正以該注音序列開頭的官方字音，
  // 不使用「同聲母亂補字」。
  for(const [base,chars] of Object.entries(MOE_BASE)){
    if(base.startsWith(input)){
      for(const ch of chars) if(!result.includes(ch)) result.push(ch);
    }
  }
  return result.slice(0,30);
}

console.info('[注音發聲板 v12 / MOE]',
  '精確讀音鍵:', Object.keys(MOE_EXACT).length,
  '基本音節:', Object.keys(MOE_BASE).length);
